// Generates app design tokens from tokens/app.json:
//   - src/css/_tokens.scss (CSS custom properties inside @layer tokens)
// Run: npm run build:tokens
import { mkdir } from 'node:fs/promises'
import path from 'node:path'

import StyleDictionary from 'style-dictionary'

const ROOT = path.resolve(import.meta.dirname, '..')
const STYLES_DIR = path.join(ROOT, 'src/css').replace(/\\/g, '/')
const HEADER =
  '/* GENERATED by scripts/build-tokens.mjs from tokens/app.json — do not edit. */\n'

const sd = new StyleDictionary({
  source: [path.join(ROOT, 'tokens/app.json')],
  hooks: {
    formats: {
      'scss/tokens-layer': ({ dictionary }) => {
        const lines = dictionary.allTokens.map(
          (token) => `    --${token.name}: ${token.value};`
        )
        return `${HEADER}@layer tokens {\n  :root {\n${lines.join('\n')}\n  }\n}\n`
      },
    },
  },
  platforms: {
    scss: {
      transformGroup: 'css',
      buildPath: `${STYLES_DIR}/`,
      files: [{ destination: '_tokens.scss', format: 'scss/tokens-layer' }],
    },
  },
})

await mkdir(STYLES_DIR, { recursive: true })
await sd.buildAllPlatforms()
console.log('tokens: generated src/css/_tokens.scss')
